import json
import csv

# Combine data from both JSONs
all_records = {}

# From 0623_tue_1150.json
with open('0623_tue_1150.json', 'r', encoding='utf-8') as f:
    data1 = json.load(f)
    for record in data1:
        data = record.get('data', {})
        record_id = data.get('record_id')
        if not record_id:
            continue

        if record_id not in all_records:
            all_records[record_id] = {
                'record_id': record_id,
                'source': data.get('corpus', ''),
                'annotator_note': '',
                'annotator_rephrasing': '',
                'annotator_review': ''
            }

        # Extract textarea fields from annotations
        for ann in record.get('annotations', []):
            for result in ann.get('result', []):
                from_name = result.get('from_name')
                if from_name in ['annotator_note', 'annotator_rephrasing', 'annotator_review']:
                    text = result.get('value', {}).get('text', [])
                    if text and isinstance(text, list):
                        text = ' '.join(text)
                    if text and not all_records[record_id].get(from_name):
                        all_records[record_id][from_name] = text

# From completion_results.json
with open('completion_results.json', 'r', encoding='utf-8') as f:
    data2 = json.load(f)
    for record in data2:
        data = record.get('data', {})
        record_id = data.get('record_id')
        if not record_id:
            continue

        if record_id not in all_records:
            all_records[record_id] = {
                'record_id': record_id,
                'source': data.get('corpus', ''),
                'annotator_note': '',
                'annotator_rephrasing': '',
                'annotator_review': ''
            }

        # Extract textarea fields from annotations
        for ann in record.get('annotations', []):
            for result in ann.get('result', []):
                from_name = result.get('from_name')
                if from_name in ['annotator_note', 'annotator_rephrasing', 'annotator_review']:
                    text = result.get('value', {}).get('text', [])
                    if text and isinstance(text, list):
                        text = ' '.join(text)
                    if text and not all_records[record_id].get(from_name):
                        all_records[record_id][from_name] = text

print(f"Total unique records: {len(all_records)}")

# Write to tmp.tsv
fieldnames = ['record_id', 'source', 'annotator_note', 'annotator_rephrasing', 'annotator_review']
with open('tmp.tsv', 'w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter='\t')
    writer.writeheader()
    for record_id in sorted(all_records.keys()):
        writer.writerow(all_records[record_id])

print("✓ tmp.tsv populated successfully")
print(f"Sample rows:")
for i, (rid, rec) in enumerate(sorted(all_records.items())[:3]):
    print(f"  {rid}: {rec['source']}")
EOF
", "explanation": "Populate tmp.tsv with annotator fields from both JSON files", "goal": "Fill TSV with annotation data including notes, rephrasings, and reviews", "mode": "sync"}

